/**
 * Minimal ambient declaration for the `cloudflare:workers` virtual module.
 *
 * The full, per-app `cloudflare:workers` typing is generated by
 * `@cloudflare/config` into each app's `.cloudflare/types/index.d.ts`. When
 * `@ssa/cloudflare` is type-checked on its own (without an app's generated
 * types), only this minimal shape is needed: the module exposes the
 * runtime-injected `env` object, typed as the `Cloudflare.Env` interface
 * that each app augments.
 */
declare module "cloudflare:workers" {
  export const env: Cloudflare.Env;
}
